function parseSms(raw) {
  if (typeof raw.phoneNumber !== "string") throw new Error("phoneNumber required");
  return { kind: "sms", phoneNumber: raw.phoneNumber };
}

function parseEmail(raw) {
  if (typeof raw.emailAddress !== "string") throw new Error("emailAddress required");
  return { kind: "email", emailAddress: raw.emailAddress };
}

function parsePush(raw) {
  if (typeof raw.deviceToken !== "string") throw new Error("deviceToken required");
  return { kind: "push", deviceToken: raw.deviceToken };
}

function parseUrgency(raw) {
  if (raw.kind === "immediate") return { kind: "immediate" };
  if (raw.kind === "scheduled" && typeof raw.sendAt === "string") {
    return { kind: "scheduled", sendAt: raw.sendAt };
  }
  throw new Error("invalid urgency");
}

function parseKind(raw, allowed) {
  if (!allowed.includes(raw.kind)) throw new Error("unknown kind");
  return raw.kind;
}

function parseChannel(raw) {
  if (typeof raw !== "object" || raw === null) throw new Error("not an object");
  const fields = { email: "emailAddress", sms: "phoneNumber", push: "deviceToken" };
  const field = fields[raw.kind];
  if (field === undefined) throw new Error("unknown kind");
  if (typeof raw[field] !== "string") throw new Error(field + " required");
  return { kind: raw.kind, [field]: raw[field] };
}

function parseDelivery(raw) {
  if (typeof raw !== "object" || raw === null) throw new Error("not an object");
  const fields = { pickup: "storeId", courier: "address" };
  const field = fields[raw.kind];
  if (field === undefined) throw new Error("unknown kind");
  if (typeof raw[field] !== "string") throw new Error(field + " required");
  return { kind: raw.kind, [field]: raw[field] };
}

function parsePayment(raw) {
  if (typeof raw !== "object" || raw === null) throw new Error("not an object");
  const fields = { card: "cardToken", invoice: "accountId" };
  const field = fields[raw.kind];
  if (field === undefined) throw new Error("unknown kind");
  if (typeof raw[field] !== "string") throw new Error(field + " required");
  return { kind: raw.kind, [field]: raw[field] };
}
